// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, GorillaServerOptions{})
}

type GorillaServerOptions struct {
	BaseURL          string
	BaseRouter       *mux.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r *mux.Router) http.Handler {
	return HandlerWithOptions(si, GorillaServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r *mux.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, GorillaServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options GorillaServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = mux.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.HandleFunc(options.BaseURL+"/api/v1/auth/setup", wrapper.GetSetup).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/auth/setup", wrapper.SetupAdmin).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/auth/login", wrapper.Login).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/auth/refresh", wrapper.RefreshSession).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/accounts", wrapper.ListAccounts).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/accounts", wrapper.CreateAccount).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/accounts/{id}", wrapper.UpdateAccount).Methods(http.MethodPut)

	r.HandleFunc(options.BaseURL+"/api/v1/accounts/{id}/password", wrapper.ResetPassword).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/audit", wrapper.ListAudit).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/service-accounts", wrapper.ListServiceAccounts).Methods(http.MethodGet)

	r.HandleFunc(options.BaseURL+"/api/v1/service-accounts", wrapper.CreateServiceAccount).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/service-accounts/{id}", wrapper.UpdateServiceAccount).Methods(http.MethodPut)

	r.HandleFunc(options.BaseURL+"/api/v1/service-accounts/{id}/key", wrapper.RotateServiceAccountKey).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/v1/auth/service", wrapper.LoginServiceAccount).Methods(http.MethodPost)

	return r
}

